describe('Sidebar toggle function', () => {
  let sidebar;
  let resizer;
  let toggleButton;

  beforeEach(() => {
    sidebar = document.createElement('div');
    resizer = document.createElement('div');
    toggleButton = document.createElement('button');
    sidebar.style.setProperty('--sidebar-width', '200');
    sidebar.style.setProperty('--sidebar-min-width', '100');
    sidebar.style.setProperty('--sidebar-max-width', '400');
    sidebar.hidden = true;
    document.body.appendChild(sidebar);
    document.body.appendChild(resizer);
    document.body.appendChild(toggleButton);
    sidebar = new Sidebar({ sidebar, resizer, toggleButton }, true, true);
  });

  afterEach(() => {
    document.body.removeChild(sidebar._sidebar);
    document.body.removeChild(resizer);
    document.body.removeChild(toggleButton);
  });

  test('should toggle the visibility of the sidebar', () => {
    expect(sidebar._isOpen).toBe(false);
    expect(sidebar._sidebar.hidden).toBe(true);

    sidebar.toggle();

    expect(sidebar._isOpen).toBe(true);
    expect(sidebar._sidebar.hidden).toBe(false);

    sidebar.toggle();

    expect(sidebar._isOpen).toBe(false);
    expect(sidebar._sidebar.hidden).toBe(true);
  });

  test('should toggle the visibility of the sidebar with a specific value', () => {
    expect(sidebar._isOpen).toBe(false);
    expect(sidebar._sidebar.hidden).toBe(true);

    sidebar.toggle(true);

    expect(sidebar._isOpen).toBe(true);
    expect(sidebar._sidebar.hidden).toBe(false);

    sidebar.toggle(false);

    expect(sidebar._isOpen).toBe(false);
    expect(sidebar._sidebar.hidden).toBe(true);
  });
});

